/* tamemark browser bundle, generated by scripts/build-browser.js */
(function (global) {
  'use strict';
  const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' };
  const TAG = /<\/?[a-zA-Z][^>]*>/g;
  const SAFE_URL = /^(https?:|mailto:|\/|#|\.)/i;

  function escapeHtml(text) {
    return text.replace(/[&<>"]/g, (character) => ESCAPES[character]);
  }

  function inline(text, options) {
    const pieces = text.split('`');
    return pieces.map((piece, index) => {
      if (index % 2 === 1) return `<code>${escapeHtml(piece)}</code>`;
      const tags = [];
      let html = piece.replace(TAG, (tag) => {
        if (!options.allowHtml) return '';
        tags.push(tag);
        return `\u0000${tags.length - 1}\u0000`;
      });
      html = escapeHtml(html)
        .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
        .replace(/\*([^*]+)\*/g, '<em>$1</em>')
        .replace(/\[([^\]^][^\]]*)\]\(([^)\s]+)\)/g, (_, label, url) => (
          SAFE_URL.test(url) ? `<a href="${url}">${label}</a>` : label
        ));
      for (const extension of options.extensions) {
        if (extension.inline) html = extension.inline(html);
      }
      return html.replace(/\u0000(\d+)\u0000/g, (_, index) => tags[Number(index)]);
    }).join('');
  }

  function render(markdown, options = {}) {
    const settings = {
      allowHtml: Boolean(options.allowHtml),
      extensions: options.extensions || [],
    };
    const blocks = markdown.replace(/\r\n/g, '\n').trim().split(/\n\s*\n/);
    const output = [];
    for (const block of blocks) {
      const claimed = settings.extensions.some((extension) => (
        extension.block && extension.block(block)
      ));
      if (claimed) continue;
      const heading = block.match(/^(#{1,6})\s+(.*)$/);
      if (heading) {
        const level = heading[1].length;
        output.push(`<h${level}>${inline(heading[2], settings)}</h${level}>`);
      } else if (block.startsWith('<')) {
        if (settings.allowHtml) output.push(block);
      } else if (block.split('\n').every((line) => line.startsWith('- '))) {
        const items = block.split('\n')
          .map((line) => `<li>${inline(line.slice(2), settings)}</li>`);
        output.push(`<ul>\n${items.join('\n')}\n</ul>`);
      } else {
        output.push(`<p>${inline(block.replace(/\n/g, ' '), settings)}</p>`);
      }
    }
    for (const extension of settings.extensions) {
      if (extension.finish) output.push(...extension.finish(settings));
    }
    return `${output.join('\n')}\n`;
  }
  global.tamemark = { render: (markdown, options = {}) => render(markdown, { ...options, extensions: [] }) };
})(typeof window !== 'undefined' ? window : globalThis);
